        "type": "Raw",
        "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
      }
    },
    "runAfter": {},
    "description": "Removes a content type from the site by its StringId (get it from contenttype-list).",
    "metadata": {
      "operationMetadataId": "a1b2c3d4-0071-4000-8000-000000000002"
    }
  }
}

{
  "id": "20spo-ctype-003-add",
  "brandColor": "#007ee5",
  "icon": "https://conn-afd-prod-endpoint-bmc9bqahasf3grgk.b01.azurefd.net/v1.0.1769/1.0.1769.4352/sharepointonline/icon.png",
  "isTrigger": false,
  "operationName": "contenttype-add",
  "operationDefinition": {
    "type": "OpenApiConnection",
    "inputs": {
      "host": {
        "connectionName": "shared_sharepointonline",
        "operationId": "HttpRequest",
        "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
      },
      "parameters": {
        "dataset": "{{SITE_URL}}",
        "parameters/method": "POST",
        "parameters/uri": "_api/web/contenttypes",
        "parameters/headers": {
          "Accept": "application/json;odata=verbose",
          "Content-Type": "application/json;odata=verbose"
        },
        "parameters/body": "{\"__metadata\": {\"type\": \"SP.ContentType\"}, \"Id\": {\"StringValue\": \"{{CONTENT_TYPE_ID}}\"}, \"Name\": \"{{CONTENT_TYPE_NAME}}\", \"Group\": \"{{CONTENT_TYPE_GROUP}}\"}"
      },
      "authentication": {
        "type": "Raw",
        "value": "@json(decodeBase64(triggerOutputs().headers['X-MS-APIM-Tokens']))['$ConnectionKey']"
      }
    },
    "runAfter": {},
    "description": "Creates a new site content type. CONTENT_TYPE_ID must be the full hex ID prefixed with the parent's ID (e.g. child of Item 0x01 -> 0x0100AB...); get parent IDs from contenttype-list.",
    "metadata": {
      "operationMetadataId": "a1b2c3d4-0071-4000-8000-000000000003"
    }
  }
}
